import re
from decimal import Context, Decimal, InvalidOperation

MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")
_PLAIN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _to_decimal(value):
    if isinstance(value, bool):
        raise ValueError("invalid amount type")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, str):
        if not _PLAIN.fullmatch(value):
            raise ValueError("invalid amount string")
        return Decimal(value)  # exact; independent of the global context
    raise ValueError("invalid amount type")


def parse_amount(value):
    d = _to_decimal(value)
    if not d.is_finite():
        raise ValueError("amount must be finite")
    if d <= 0:
        raise ValueError("amount must be positive")
    if d > MAX_AMOUNT:
        raise ValueError("amount too large")
    # Local context so the global one is never used or modified.
    ctx = Context(prec=max(len(d.as_tuple().digits) + 4, 28))
    try:
        q = d.quantize(_CENT, context=ctx)
    except InvalidOperation:
        raise ValueError("invalid amount")
    if q != d:
        raise ValueError("amount not representable in cents")
    return q


def format_amount(value):
    return format(value, ".2f")
EOF
